const listBudgets = `-- name: ListBudgets :many
SELECT b.id, b.tenant_id, b.property_id, b.year_start, b.version, b.name, b.description, b.status, b.copied_from_id, b.activated_at, b.activated_by, b.approved_by, b.archived_at, b.created_at, b.created_by, b.updated_at, b.updated_by,
       (SELECT count(DISTINCT l.account_id) FROM budget_lines l WHERE l.property_id = b.property_id AND l.budget_id = b.id)::int AS account_count,
       COALESCE((SELECT sum(l.amount) FROM budget_lines l JOIN gl_accounts a ON a.property_id = l.property_id AND a.id = l.account_id
                  WHERE l.property_id = b.property_id AND l.budget_id = b.id AND a.account_type = 'REVENUE'), 0)::numeric AS total_revenue,
       COALESCE((SELECT sum(l.amount) FROM budget_lines l JOIN gl_accounts a ON a.property_id = l.property_id AND a.id = l.account_id
                  WHERE l.property_id = b.property_id AND l.budget_id = b.id AND a.account_type = 'EXPENSE'), 0)::numeric AS total_expense
FROM budgets b
WHERE b.tenant_id = $1 AND b.property_id = $2
  AND ($3::date IS NULL OR b.year_start = $3::date)
  AND ($4::text IS NULL OR b.status = $4::text)
ORDER BY b.year_start DESC, b.version DESC
`

type ListBudgetsParams struct {
	TenantID   int64
	PropertyID int64
	YearStart  *civil.Date
	Status     *string
}

type ListBudgetsRow struct {
	ID           int64
	TenantID     int64
	PropertyID   int64
	YearStart    civil.Date
	Version      int32
	Name         string
	Description  *string
	Status       string
	CopiedFromID *int64
	ActivatedAt  *time.Time
	ActivatedBy  *int64
	ApprovedBy   *int64
	ArchivedAt   *time.Time
	CreatedAt    time.Time
	CreatedBy    *int64
	UpdatedAt    time.Time
	UpdatedBy    *int64
	AccountCount int32
	TotalRevenue decimal.Decimal
	TotalExpense decimal.Decimal
}

func (q *Queries) ListBudgets(ctx context.Context, arg ListBudgetsParams) ([]ListBudgetsRow, error) {
	rows, err := q.db.Query(ctx, listBudgets,
		arg.TenantID,
		arg.PropertyID,
		arg.YearStart,
		arg.Status,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListBudgetsRow{}
	for rows.Next() {
		var i ListBudgetsRow
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.PropertyID,
			&i.YearStart,
			&i.Version,
			&i.Name,
			&i.Description,
			&i.Status,
			&i.CopiedFromID,
			&i.ActivatedAt,
			&i.ActivatedBy,
			&i.ApprovedBy,
			&i.ArchivedAt,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.UpdatedAt,
			&i.UpdatedBy,
			&i.AccountCount,
			&i.TotalRevenue,
			&i.TotalExpense,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

