const updateBudgetText = `-- name: UpdateBudgetText :one
UPDATE budgets SET name = $1, description = $2, updated_by = $3
WHERE tenant_id = $4 AND property_id = $5 AND id = $6
RETURNING id
`

type UpdateBudgetTextParams struct {
	Name        string
	Description *string
	ActorID     *int64
	TenantID    int64
	PropertyID  int64
	ID          int64
}

func (q *Queries) UpdateBudgetText(ctx context.Context, arg UpdateBudgetTextParams) (int64, error) {
	row := q.db.QueryRow(ctx, updateBudgetText,
		arg.Name,
		arg.Description,
		arg.ActorID,
		arg.TenantID,
		arg.PropertyID,
		arg.ID,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}
